CREATE INDEX IF NOT EXISTS idx_onboarding_tasks_onboarding_id ON lifecycle.onboarding_tasks (onboarding_id);

CREATE INDEX IF NOT EXISTS idx_onboarding_tasks_status ON lifecycle.onboarding_tasks (status);

-- GIN index for audit metadata JSONB queries
CREATE INDEX IF NOT EXISTS idx_onboarding_tasks_metadata_gin ON lifecycle.onboarding_tasks USING GIN (metadata);
CREATE INDEX IF NOT EXISTS idx_onboarding_tasks_metadata_deleted_at ON lifecycle.onboarding_tasks ((metadata->>'deleted_at'));
CREATE INDEX IF NOT EXISTS idx_onboarding_tasks_metadata_created_at ON lifecycle.onboarding_tasks ((metadata->>'created_at'));
